```
class ROT {
  constructor(o) { return o; }
}

class Stamp extends ROT {
  #value;
  constructor(o, value) {
    super(o);
    this.#value = value;
  }
}
let stamp = (o, value) => { new Stamp(o, value); };

const obj = {};
stamp(obj, 1);
stamp(obj, 2); // error
```

